def make_router():
    routes = {}

    def add_route(method, path, handler):
        routes[(method, path)] = handler

    def handle(method, path, query=None, body=None):
        handler = routes.get((method, path))
        if handler is None:
            return {"status": 404, "body": {"error": "not found"}}
        try:
            result = handler(query or {}, body or {})
        except ValueError as exc:
            return {"status": 400, "body": {"error": str(exc)}}
        return {"status": 200, "body": result}

    return add_route, handle


def get_products(query, body):
    page = int(query.get("page", "1"))
    return {"page": page, "products": []}


def create_user(query, body):
    if "name" not in body:
        raise ValueError("missing field: name")
    return {"id": 1, "name": body["name"]}


add_route, handle = make_router()
add_route("GET", "/products", get_products)
add_route("POST", "/users", create_user)

print(handle("GET", "/products", query={"page": "2"}))
print(handle("POST", "/users", body={"name": "Alice"}))
print(handle("POST", "/users", body={}))
print(handle("GET", "/missing"))
